from pathlib import Path
import os,json
R=Path(__file__).resolve().parent; O=R/'outputs'
os.environ['MPLCONFIGDIR']=str(O/'matplotlib_cache')
os.environ['XDG_CACHE_HOME']=str(O/'cache')
(O/'cache').mkdir(exist_ok=True)
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import pandas as pd
from src.features import TASKS
cfg=json.loads((O/'selected_config.json').read_text()); exp=pd.read_csv(O/'experiments.csv'); summary=pd.read_csv(O/'cv_summary.csv'); err=pd.read_csv(O/'errors_selected.csv'); oof=pd.read_csv(O/'errors_oof_selected.csv'); imp=pd.read_csv(O/'feature_importance.csv'); ana=pd.read_csv(O/'error_analysis.csv')
fig,ax=plt.subplots(figsize=(9,7)); z=imp.head(20).iloc[::-1]; ax.barh(z.feature,z.importance); ax.set_xlabel('CatBoost PredictionValuesChange'); ax.set_title('Final primary component: top 20 features'); fig.tight_layout(); fig.savefig(O/'feature_importance.png',dpi=160); plt.close(fig)
plot_summary=summary.copy()
if len(cfg['models'])>1:
 blends=pd.read_csv(O/'ensemble_experiments.csv'); selected_blend=blends[blends.classifier_weight.eq(cfg['classifier_weight'])].iloc[0]
 plot_summary=pd.concat([pd.DataFrame([{'model':'selected_blend','mean_top3':cfg['cv_mean_top3'],'std_top3':selected_blend.std_top3}]),plot_summary],ignore_index=True)
fig,ax=plt.subplots(figsize=(10,5)); ax.bar(plot_summary.model,plot_summary.mean_top3,yerr=plot_summary.std_top3,capsize=4); ax.axhline(.352,color='gray',linestyle='--',label='Quoted test reference (different split)'); ax.set_ylim(0,1); ax.set_ylabel('Controller-CV mean top-3 ± fold SD'); ax.tick_params(axis='x',rotation=35); ax.legend(); fig.tight_layout(); fig.savefig(O/'cv_comparison.png',dpi=160); plt.close(fig)
# Confusion on same aircraft vs different aircraft for each missed sample's first prediction.
selected=cfg['models']; val=pd.read_csv(R.parent/'validation.csv'); preds=pd.read_csv(O/'validation_predictions.csv'); first=preds.assign(row_index=preds.prediction.str.split().str[0].astype(int)).merge(val,on=['sample_id','row_index']); true=val[val.target_index.eq(1)]; pair=true.merge(first,on='sample_id',suffixes=('_true','_pred'))
pat='^('+'|'.join(TASKS)+')_'; pair['same_aircraft']=pair.task_name_true.str.replace(pat,'',regex=True).eq(pair.task_name_pred.str.replace(pat,'',regex=True)); pair[['sample_id','task_name_true','task_name_pred','same_aircraft']].to_csv(O/'same_aircraft_confusion.csv',index=False)
lines=['# Measured results','',f"Selected models: {', '.join(selected)}; final trees: {cfg['iterations']}.",'',f"Official validation (fixed CV-chosen tree counts): top-1 {err.hit1.mean():.4%}, top-2 {err.hit2.mean():.4%}, **top-3 {err.hit3.mean():.4%}** ({len(err)} snapshots).",f"Controller CV: selected mean fold top-3 **{cfg['cv_mean_top3']:.4%}**. Pooled OOF top-3 {oof.hit3.mean():.4%}; equal-controller mean {oof.groupby('atco').hit3.mean().mean():.4%}.",'','## Controller CV','',summary.to_markdown(index=False) if False else '```\n'+summary.to_string(index=False)+'\n```','', '## Official validation experiments','', '```\n'+exp[exp.validation_scheme.eq('official')][['model','top1','top2','top3','trees']].to_string(index=False)+'\n```','', '## Selected official-validation sessions','', '```\n'+ana[ana.dimension.eq('session')].to_string(index=False)+'\n```','', '## Task errors','', '```\n'+ana[ana.dimension.eq('task_type')].to_string(index=False)+'\n```','',f"True task ranked exactly fourth: {int(err['rank'].eq(4).sum())} / {len(err)} samples. Coordination-task recall should be read separately from frequent assume/transfer tasks; small task subsets are noisy.",'', '## Feature interpretation','', '```\n'+imp.head(15).to_string(index=False)+'\n```','', 'Task type differentiates jobs associated with the same aircraft. List ranks describe relative urgency among competing candidates. Task age measures persistence; sector and exit timing describe impending entry or handover. Action history indicates recent controller attention. Missing-state patterns can distinguish aircraft not yet assumed. These associations explain model use, not causal effects.','', '## Scope and limitations','', 'All scores above are measured locally, not Kaggle scores. Hyperparameters/checkpoints and ensemble choices use held-out controllers but share model-selection folds, so uncertainty includes selection optimism and correlated snapshots. No public-leaderboard feedback was used. Identity and clock features were tested explicitly; the selected configuration documents whether either was retained. Final training includes validation, so controller 020 is partially known while 023 remains unseen. No test labels, pseudo-labels, future target history, or label smoothing were used.','', 'Original input hashes and final submission validation passed; submission contains exactly 1,863 samples. Component-only alternatives are retained in outputs; the primary submission follows controller-CV selection rather than the highest exploratory official score.']
(O/'results.md').write_text('\n'.join(lines)+'\n')
read=R/'README.md'; text=read.read_text().split('\n## Run results\n')[0]; text+='\n## Run results\n\n'+lines[2]+'\n\n'+lines[4]+'\n\n'+lines[5]+'\n\nSee `outputs/results.md` for all measured comparisons and errors.\n'; read.write_text(text)
print('\n'.join(lines[:6]))
